using UnityEngine;

/// <summary>
/// 范围伤害技能效果：以施法者或目标点为中心造成圆形范围伤害。
/// 右键 -> Create -> Game -> Skill Effect -> AoE Damage
/// </summary>
[CreateAssetMenu(fileName = "AoEEffect", menuName = "Game/Skill Effect/AoE Damage")]
public class AoESkillEffect : SkillEffectBase
{
    [Header("范围配置")]
    [Tooltip("伤害半径")]
    public float radius = 3f;

    [Tooltip("是否以施法者为中心（否则以施法方向前方2单位处为中心）")]
    public bool centeredOnCaster = true;

    [Tooltip("打击特效预制体（可选）")]
    public GameObject impactVfx;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        Vector2 center = centeredOnCaster
            ? (Vector2)caster.CasterTransform.position
            : (Vector2)caster.CasterTransform.position + direction * 2f;

        float damage = caster.GetAttackStrength() * damageMultiplier;

        if (impactVfx != null)
            Instantiate(impactVfx, center, Quaternion.identity);

        Collider2D[] hits = Physics2D.OverlapCircleAll(center, radius);
        string enemyTag = ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";

        foreach (var hit in hits)
        {
            if (!hit.CompareTag(enemyTag)) continue;
            if (hit.TryGetComponent<IDamageable>(out var d))
                d.TakeDamage(damage);
        }
    }
}

using UnityEngine;

/// <summary>
/// 冲刺技能效果：施法者向目标方向瞬移一段距离。
/// 右键 -> Create -> Game -> Skill Effect -> Dash
/// </summary>
[CreateAssetMenu(fileName = "DashEffect", menuName = "Game/Skill Effect/Dash")]
public class DashSkillEffect : SkillEffectBase
{
    [Header("冲刺配置")]
    [Tooltip("冲刺距离")]
    public float distance = 5f;

    [Tooltip("冲刺时间（秒），0 = 瞬间）")]
    public float duration = 0.15f;

    [Tooltip("冲刺过程中是否无敌")]
    public bool invincibleDuringDash = true;

    [Tooltip("冲刺拖影特效预制体（可选）")]
    public GameObject trailVfx;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        MonoBehaviour mono = caster.CasterTransform.GetComponent<MonoBehaviour>();
        if (mono == null) return;

        mono.StartCoroutine(DashRoutine(caster, direction));
    }

    private System.Collections.IEnumerator DashRoutine(ISkillCaster caster, Vector2 dir)
    {
        Transform t = caster.CasterTransform;
        Vector3 start = t.position;
        Vector3 end = start + (Vector3)(dir * distance);
        float elapsed = 0f;

        if (trailVfx != null)
            Instantiate(trailVfx, t.position, Quaternion.identity, t);

        while (elapsed < duration)
        {
            elapsed += Time.deltaTime;
            float tVal = elapsed / duration;
            t.position = Vector3.Lerp(start, end, tVal);
            yield return null;
        }

        t.position = end;
    }
}

using UnityEngine;

/// <summary>
/// 治疗技能效果：恢复施法者自身生命值。
/// 右键 -> Create -> Game -> Skill Effect -> Heal
/// </summary>
[CreateAssetMenu(fileName = "HealEffect", menuName = "Game/Skill Effect/Heal")]
public class HealSkillEffect : SkillEffectBase
{
    [Header("治疗配置")]
    [Tooltip("基础治疗量")]
    public float baseHealAmount = 20f;

    [Tooltip("是否受攻击力加成")]
    public bool scaleWithAttack = true;

    [Tooltip("治疗特效预制体（可选）")]
    public GameObject healVfx;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        float healAmount = scaleWithAttack
            ? baseHealAmount + caster.GetAttackStrength() * damageMultiplier * 0.5f
            : baseHealAmount;

        if (caster.CasterTransform.TryGetComponent<IHealable>(out var healable))
        {
            healable.Heal(healAmount);
        }

        if (healVfx != null)
            Instantiate(healVfx, caster.CasterTransform.position, Quaternion.identity);
    }
}

using System;
using UnityEngine;

public class Projectile : MonoBehaviour
{
    public enum OwnerType { Player, Enemy }

    /// <summary>全局投射物命中事件: (projectile, hitTarget)</summary>
    public static event Action<Projectile, GameObject> OnAnyProjectileHit;

    [Header("子弹参数")]
    [SerializeField] private float speed = 8f;
    [SerializeField] private float damage = 10f;
    [SerializeField] private float lifeTime = 3f;

    /// <summary>投射物所属主人GameObject</summary>
    public GameObject Caster { get; private set; }

    private Vector2 _direction;
    private OwnerType _owner;
    private bool _isInitialized;

    /// <param name="caster">投射物所有者GameObject，可选</param>
    public void Initialize(Vector2 dir, float spd, float dmg, OwnerType owner, GameObject caster = null)
    {
        _direction = dir.normalized;
        speed = spd;
        damage = dmg;
        _owner = owner;
        Caster = caster ?? gameObject;
        _isInitialized = true;

        // 用 Invoke 延时回收（替代 Destroy(gameObject, lifeTime)）
        CancelInvoke(nameof(ReturnToPool));
        Invoke(nameof(ReturnToPool), lifeTime);
    }

    /// <summary>重置状态（池化复用时由 ProjectilePool 间接调用）</summary>
    public void ResetState()
    {
        _isInitialized = false;
        _direction = Vector2.zero;
        Caster = null;
        CancelInvoke(nameof(ReturnToPool));
    }

    void Update()
    {
        if (!_isInitialized) return;
        transform.Translate(_direction * speed * Time.deltaTime, Space.World);
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!_isInitialized) return;

        if (other.CompareTag("Obstacles"))
        {
            ReturnToPool();
            return;
        }

        string targetTag = _owner == OwnerType.Player ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        IDamageable damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            damageable.TakeDamage(damage);
            OnAnyProjectileHit?.Invoke(this, other.gameObject);
        }

        ReturnToPool();
    }

    private void OnBecameInvisible()
    {
        ReturnToPool();
    }

    private void ReturnToPool()
    {
        if (!_isInitialized) return;
        ResetState();
        ProjectilePool.Return(gameObject);
    }
}

